package com.bestdps.calc;

import com.bestdps.data.GearItem;
import com.bestdps.data.GearSlot;
import com.bestdps.data.StatBlock;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;

public final class Loadout
{
	private final EnumMap<GearSlot, GearItem> gear;
	private final StatBlock offensive;
	private final StatBlock bonuses;
	private final int cost;

	public Loadout(Map<GearSlot, GearItem> gear)
	{
		this.gear = new EnumMap<>(GearSlot.class);
		this.gear.putAll(gear);

		StatBlock offensiveTotal = StatBlock.ZERO;
		StatBlock bonusTotal = StatBlock.ZERO;
		int totalCost = 0;
		for (GearItem item : this.gear.values())
		{
			if (item == null)
			{
				continue;
			}
			offensiveTotal = offensiveTotal.plus(item.getOffensive());
			bonusTotal = bonusTotal.plus(item.getBonuses());
			totalCost += item.getPriceOrZero();
		}
		this.offensive = offensiveTotal;
		this.bonuses = bonusTotal;
		this.cost = totalCost;
	}

	public GearItem get(GearSlot slot)
	{
		return gear.get(slot);
	}

	public GearItem getWeapon()
	{
		return gear.get(GearSlot.WEAPON);
	}

	public Map<GearSlot, GearItem> getGear()
	{
		return Collections.unmodifiableMap(gear);
	}

	public StatBlock getOffensive()
	{
		return offensive;
	}

	public StatBlock getBonuses()
	{
		return bonuses;
	}

	public int getCost()
	{
		return cost;
	}
}

package com.bestdps.calc;

import com.bestdps.data.MonsterStats;
import com.bestdps.data.SpellStats;

public final class OptimizationRequest
{
	private final MonsterStats monster;
	private final CombatStyle style;
	private final PlayerLevels levels;
	private final PrayerBonuses prayers;
	private final SpellStats spell;
	private final int budget;
	private final CandidateMode candidateMode;
	private final boolean includeUntradeables;
	private final boolean onSlayerTask;
	private final OwnedItems ownedItems;
	private final RequirementProfile requirementProfile;
	private final int resultLimit;

	public OptimizationRequest(
		MonsterStats monster,
		CombatStyle style,
		PlayerLevels levels,
		PrayerBonuses prayers,
		SpellStats spell,
		int budget,
		CandidateMode candidateMode,
		boolean includeUntradeables,
		boolean onSlayerTask,
		OwnedItems ownedItems,
		int resultLimit)
	{
		this(monster, style, levels, prayers, spell, budget, candidateMode, includeUntradeables, onSlayerTask, ownedItems, RequirementProfile.MAXED, resultLimit);
	}

	public OptimizationRequest(
		MonsterStats monster,
		CombatStyle style,
		PlayerLevels levels,
		PrayerBonuses prayers,
		SpellStats spell,
		int budget,
		CandidateMode candidateMode,
		boolean includeUntradeables,
		boolean onSlayerTask,
		OwnedItems ownedItems,
		RequirementProfile requirementProfile,
		int resultLimit)
	{
		this.monster = monster;
		this.style = style;
		this.levels = levels;
		this.prayers = prayers == null ? PrayerBonuses.NONE : prayers;
		this.spell = spell;
		this.budget = Math.max(0, budget);
		this.candidateMode = candidateMode == null ? CandidateMode.BUDGET : candidateMode;
