package com.bestdps.calc;

import com.bestdps.data.GearItem;
import java.util.Locale;

final class RangedAmmo
{
	private RangedAmmo()
	{
	}

	static boolean compatible(GearItem ammo, GearItem weapon)
	{
		if (ammo == null)
		{
			return true;
		}
		if (projectileMatches(ammo, weapon))
		{
			return true;
		}
		return !weaponUsesProjectileAmmo(weapon) && passiveAmmoSlotItem(ammo);
	}

	static boolean strengthApplies(GearItem ammo, GearItem weapon)
	{
		return ammo != null && projectileMatches(ammo, weapon);
	}

	private static boolean weaponUsesProjectileAmmo(GearItem weapon)
	{
		String weaponName = name(weapon);
		String category = category(weapon);
		if (weaponName.contains("blowpipe")
			|| weaponName.contains("ballista")
			|| weaponName.contains("karil") && weaponName.contains("crossbow"))
		{
			return true;
		}
		if (weaponName.contains("crystal bow") || weaponName.contains("bow of faerdhinen"))
		{
			return false;
		}
		return category.contains("bow") || category.contains("crossbow");
	}

	private static boolean projectileMatches(GearItem ammo, GearItem weapon)
	{
		String ammoName = name(ammo);
		String weaponName = name(weapon);
		String category = category(weapon);
		if (weaponName.contains("blowpipe"))
		{
			return ammoName.contains("dart");
		}
		if (weaponName.contains("ballista"))
		{
			return ammoName.contains("javelin");
		}
		if (weaponName.contains("karil") && weaponName.contains("crossbow"))
		{
			return ammoName.contains("bolt rack");
		}
		if (weaponName.contains("crystal bow") || weaponName.contains("bow of faerdhinen"))
		{
			return false;
		}
		if (category.contains("bow") && !category.contains("crossbow"))
		{
			return ammoName.contains("arrow");
		}
		if (category.contains("crossbow"))
		{
			return ammoName.contains("bolt") && !ammoName.contains("bolt rack");
		}
		return false;
	}

	private static boolean passiveAmmoSlotItem(GearItem ammo)
	{
		return ammo.getBonuses().getRangedStrength() <= 0 && ammo.getOffensive().getRanged() <= 0;
	}

	private static String name(GearItem item)
	{
		return item == null ? "" : item.getName().toLowerCase(Locale.ROOT);
	}

	private static String category(GearItem item)
	{
		return item == null ? "" : item.getCategory().toLowerCase(Locale.ROOT);
	}
}

package com.bestdps.calc;

import com.bestdps.data.GearRequirements;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.Skill;

public final class RequirementProfile
{
	public static final RequirementProfile MAXED = new RequirementProfile(maxedLevels(), allQuests());

	private final Map<Skill, Integer> levels;
	private final Set<String> completedQuests;

	public RequirementProfile(Map<Skill, Integer> levels, Set<String> completedQuests)
	{
		EnumMap<Skill, Integer> copy = new EnumMap<>(Skill.class);
		if (levels != null)
		{
			copy.putAll(levels);
		}
		this.levels = Collections.unmodifiableMap(copy);
		this.completedQuests = Collections.unmodifiableSet(new HashSet<>(completedQuests == null ? Collections.emptySet() : completedQuests));
	}

	public boolean canEquip(GearRequirements requirements)
	{
		if (requirements == null || requirements.isEmpty())
		{
			return true;
		}
		for (Map.Entry<String, Integer> entry : requirements.getSkills().entrySet())
		{
			Skill skill = skill(entry.getKey());
			if (skill != null && levels.getOrDefault(skill, 1) < entry.getValue())
			{
				return false;
			}
		}
		for (String quest : requirements.getQuests())
		{
			if (!completedQuests.contains(quest))
			{
				return false;
			}
		}
		return true;
	}

	int level(Skill skill)
	{
		return levels.getOrDefault(skill, 1);
	}

	private static Skill skill(String name)
	{
		if (name == null)
		{
			return null;
		}
		String normalized = name.toUpperCase(Locale.ROOT);
		if ("RUNECRAFTING".equals(normalized))
		{
			normalized = "RUNECRAFT";
		}
		try
		{
			return Skill.valueOf(normalized);
		}
		catch (IllegalArgumentException ex)
		{
			return null;
		}
	}

	private static Map<Skill, Integer> maxedLevels()
	{
		EnumMap<Skill, Integer> result = new EnumMap<>(Skill.class);
		for (Skill skill : Skill.values())
		{
			if (skill != Skill.OVERALL)
			{
				result.put(skill, 99);
			}
		}
		return result;
	}

	private static Set<String> allQuests()
	{
		Set<String> result = new HashSet<>();
		for (Quest quest : Quest.values())
		{
			result.add(quest.name());
		}
		return result;
	}
}

package com.bestdps.calc;

public final class RollMath
{
	static final double SECONDS_PER_TICK = 0.6;

	private RollMath()
	{
	}

	public static double normalAccuracy(long attackRoll, long defenceRoll)
	{
		double atk = attackRoll;
		double def = defenceRoll;
		if (atk < 0)
		{
			atk = Math.min(0, atk + 2);
		}
		if (def < 0)
		{
			def = Math.min(0, def + 2);
		}
		if (atk >= 0 && def >= 0)
		{
			return atk > def
				? 1.0 - ((def + 2.0) / (2.0 * (atk + 1.0)))
				: atk / (2.0 * (def + 1.0));
		}
		if (atk >= 0)
		{
			return 1.0 - 1.0 / ((-def + 1.0) * (atk + 1.0));
		}
		if (def >= 0)
		{
			return 0.0;
		}
		double swappedAtk = -def;
		double swappedDef = -atk;
		return swappedAtk > swappedDef
			? 1.0 - ((swappedDef + 2.0) / (2.0 * (swappedAtk + 1.0)))
			: swappedAtk / (2.0 * (swappedDef + 1.0));
	}

	public static int effectiveLevel(int level, double prayer, int stanceBonus)
	{
		return (int) Math.floor(level * prayer) + stanceBonus + 8;
	}

	public static int maxHitFromEffective(int effectiveLevel, int strengthBonus)
	{
		return Math.max(0, (int) Math.floor((effectiveLevel * (strengthBonus + 64.0) + 320.0) / 640.0));
	}

	public static long attackRoll(int effectiveLevel, int attackBonus)
	{
		return (long) effectiveLevel * (attackBonus + 64L);
	}

	public static long defenceRoll(int effectiveLevel, int defenceBonus)
	{
		return (long) effectiveLevel * (defenceBonus + 64L);
	}

	public static double normalExpectedHit(double accuracy, int maxHit)
	{
		if (maxHit <= 0 || accuracy <= 0.0)
		{
			return 0.0;
		}
		return accuracy * (maxHit / 2.0 + 1.0 / (maxHit + 1.0));
	}

	public static double expectedHit(double accuracy, int minHit, int maxHit)
	{
		if (maxHit <= 0 || accuracy <= 0.0)
		{
			return 0.0;
		}
		if (minHit <= 0)
		{
			return normalExpectedHit(accuracy, maxHit);
		}
		int minimum = Math.min(minHit, maxHit);
		return accuracy * ((minimum + maxHit) / 2.0);
	}

	public static double fangAccuracy(long attackRoll, long defenceRoll)
	{
		double atk = attackRoll;
		double def = defenceRoll;
		if (atk < 0)
		{
			atk = Math.min(0, atk + 2);
		}
		if (def < 0)
		{
			def = Math.min(0, def + 2);
		}
		if (atk >= 0 && def >= 0)
		{
			return atk > def
				? 1.0 - (def + 2.0) * (2.0 * def + 3.0) / (atk + 1.0) / (atk + 1.0) / 6.0
				: atk * (4.0 * atk + 5.0) / 6.0 / (atk + 1.0) / (def + 1.0);
		}
		if (atk >= 0)
		{
			return 1.0 - 1.0 / (-def + 1.0) / (atk + 1.0);
		}
		if (def >= 0)
		{
			return 0.0;
		}
		double reversedAttack = -def;
		double reversedDefence = -atk;
		return reversedAttack < reversedDefence
			? reversedAttack * (reversedDefence * 6.0 - 2.0 * reversedAttack + 5.0) / 6.0 / (reversedDefence + 1.0) / (reversedDefence + 1.0)
			: 1.0 - (reversedDefence + 2.0) * (2.0 * reversedDefence + 3.0) / 6.0 / (reversedDefence + 1.0) / (reversedAttack + 1.0);
	}
}

package com.bestdps.data;

import java.util.Collections;
import java.util.List;
import java.util.Map;

public final class BestDpsData
{
	private final List<GearItem> gearItems;
	private final List<MonsterStats> monsters;
	private final List<SpellStats> spells;
	private final Map<Integer, GearItem> gearById;

	BestDpsData(
		List<GearItem> gearItems,
		List<MonsterStats> monsters,
		List<SpellStats> spells,
		Map<Integer, GearItem> gearById)
	{
		this.gearItems = Collections.unmodifiableList(gearItems);
		this.monsters = Collections.unmodifiableList(monsters);
		this.spells = Collections.unmodifiableList(spells);
		this.gearById = Collections.unmodifiableMap(gearById);
	}

	public List<MonsterStats> searchMonsters(String query, int limit)
	{
		String text = query == null ? "" : query.trim().toLowerCase();
		if (text.isEmpty())
		{
			return Collections.emptyList();
		}

		java.util.ArrayList<MonsterStats> exact = new java.util.ArrayList<>();
		java.util.ArrayList<MonsterStats> prefix = new java.util.ArrayList<>();
		java.util.ArrayList<MonsterStats> contains = new java.util.ArrayList<>();
		for (MonsterStats monster : monsters)
		{
			String name = monster.getName().toLowerCase();
			if (name.equals(text) || String.valueOf(monster.getId()).equals(text))
			{
				exact.add(monster);
			}
			else if (name.startsWith(text))
			{
				prefix.add(monster);
			}
			else if (monster.searchText().contains(text))
			{
				contains.add(monster);
			}
		}

		java.util.ArrayList<MonsterStats> result = new java.util.ArrayList<>(limit);
		addLimited(result, exact, limit);
		addLimited(result, prefix, limit);
		addLimited(result, contains, limit);
		return result;
	}

	private static void addLimited(List<MonsterStats> target, List<MonsterStats> source, int limit)
	{
		for (MonsterStats monster : source)
		{
			if (target.size() >= limit)
			{
				return;
			}
			target.add(monster);
		}
	}

	public GearItem getGear(int id)
	{
		return gearById.get(id);
	}

	public List<GearItem> getGearItems()
	{
		return gearItems;
	}

	public List<MonsterStats> getMonsters()
	{
		return monsters;
	}

	public List<SpellStats> getSpells()
	{
		return spells;
	}
}

package com.bestdps.data;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.zip.GZIPInputStream;

public final class BestDpsDataService
{
	private static final String GEAR_RESOURCE = "/com/bestdps/data/gear_prices.json.gz";
	private static final String REQUIREMENTS_RESOURCE = "/com/bestdps/data/equipment_requirements.json.gz";
	private static final String MONSTER_RESOURCE = "/com/bestdps/data/monsters.json.gz";
	private static final String SPELL_RESOURCE = "/com/bestdps/data/spells.json.gz";

	public BestDpsData load()
	{
		List<GearItem> gear = loadGear();
		List<MonsterStats> monsters = loadMonsters();
		List<SpellStats> spells = loadSpells();
		Map<Integer, GearItem> gearById = new HashMap<>();
		for (GearItem item : gear)
		{
			gearById.put(item.getId(), item);
		}
		return new BestDpsData(gear, monsters, spells, gearById);
	}

	private List<GearItem> loadGear()
	{
		JsonArray rows = readArray(GEAR_RESOURCE);
		Map<Integer, Map<String, Integer>> skillRequirements = loadSkillRequirements();
		List<GearItem> result = new ArrayList<>(rows.size());
		for (JsonElement element : rows)
		{
			JsonObject row = element.getAsJsonObject();
			GearSlot slot = GearSlot.fromJson(string(row, "slot"));
			if (slot == null)
			{
				continue;
			}

			result.add(new GearItem(
				integer(row, "id", 0),
				string(row, "name"),
				string(row, "version"),
				slot,
				string(row, "category"),
				integer(row, "speed", 0),
				bool(row, "isTwoHanded", false),
				bool(row, "isStandardGear", true),
				bool(row, "tradeable", false),
				nullableInteger(row, "estimatedPrice"),
				parseOffensive(row.getAsJsonObject("offensive")),
				parseDefensive(row.getAsJsonObject("defensive")),
				parseBonuses(row.getAsJsonObject("bonuses")),
				requirementsFor(
					integer(row, "id", 0),
					string(row, "name"),
					string(row, "version"),
					skillRequirements)));
		}
		result.sort(Comparator.comparing(GearItem::getName).thenComparingInt(GearItem::getId));
		return result;
	}

	private Map<Integer, Map<String, Integer>> loadSkillRequirements()
	{
		JsonArray rows = readArray(REQUIREMENTS_RESOURCE);
		Map<Integer, Map<String, Integer>> result = new HashMap<>();
		for (JsonElement element : rows)
		{
			JsonObject row = element.getAsJsonObject();
			JsonObject skills = object(row, "skills");
			Map<String, Integer> levels = new LinkedHashMap<>();
			for (Map.Entry<String, JsonElement> entry : skills.entrySet())
			{
				if (!entry.getValue().isJsonNull())
				{
					levels.put(entry.getKey(), Math.max(1, entry.getValue().getAsInt()));
				}
			}
			if (!levels.isEmpty())
			{
				result.put(integer(row, "id", 0), levels);
			}
		}
		return result;
	}

	private static GearRequirements requirementsFor(int id, String name, String version, Map<Integer, Map<String, Integer>> skillRequirements)
	{
		Map<String, Integer> skills = skillRequirements.getOrDefault(id, java.util.Collections.emptyMap());
		Set<String> quests = new LinkedHashSet<>(QuestUnlocks.forItem(id, name, version));
		return skills.isEmpty() && quests.isEmpty() ? GearRequirements.NONE : new GearRequirements(skills, quests);
	}

	private List<MonsterStats> loadMonsters()
	{
		JsonArray rows = readArray(MONSTER_RESOURCE);
		List<MonsterStats> result = new ArrayList<>(rows.size());
		for (JsonElement element : rows)
		{
			JsonObject row = element.getAsJsonObject();
			JsonObject skills = object(row, "skills");
			JsonObject offensive = object(row, "offensive");
			JsonObject defensive = object(row, "defensive");
			JsonObject weakness = object(row, "weakness");
			List<String> attributes = new ArrayList<>();
			JsonArray attrArray = array(row, "attributes");
			for (JsonElement attr : attrArray)
			{
				if (!attr.isJsonNull())
				{
					attributes.add(attr.getAsString());
				}
			}

			result.add(new MonsterStats(
				integer(row, "id", -1),
				string(row, "name"),
				string(row, "version"),
				integer(row, "level", 0),
				integer(skills, "hp", 1),
				integer(row, "size", 1),
				integer(skills, "def", 1),
				integer(skills, "magic", 1),
				integer(offensive, "magic", 0),
				parseMonsterDefences(defensive),
				attributes,
				bool(row, "is_slayer_monster", false) || knownSlayerMonster(string(row, "name")),
				string(weakness, "element"),
				integer(weakness, "severity", 0)));
		}
		result.sort(Comparator.comparing(MonsterStats::getName).thenComparing(MonsterStats::getVersion).thenComparingInt(MonsterStats::getId));
		return result;
	}

	private List<SpellStats> loadSpells()
	{
		JsonArray rows = readArray(SPELL_RESOURCE);
		List<SpellStats> result = new ArrayList<>(rows.size());
		for (JsonElement element : rows)
		{
			JsonObject row = element.getAsJsonObject();
			int maxHit = integer(row, "max_hit", 0);
			String name = string(row, "name");
			if (maxHit <= 0 && !"Magic Dart".equals(name))
			{
				continue;
			}
			result.add(new SpellStats(
				name,
				"Magic Dart".equals(name) ? 1 : maxHit,
				spellLevel(name),
				string(row, "spellbook"),
				string(row, "element")));
		}
		result.sort(Comparator.comparingInt(SpellStats::getMaxHit).thenComparing(SpellStats::getName));
		return result;
	}

